<script setup>
import { computed } from 'vue'
import { defaultBannerUrl, resolveAssetUrl } from '@/constants/assets'
import { eventState, eventStateLabel, eventReplayLink } from '@/services/eventPresentation'
import { eventGameNames } from '@/services/eventGame'
import { invitationDate } from '@/services/eventInvitation'
const props=defineProps({event:{type:Object,required:true},communities:{type:Array,default:()=>[]},notified:Boolean,notifyPending:Boolean,now:Number,emphasize:{type:Boolean,default:true}})
const emit=defineEmits(['details','notify','share'])
const date=computed(()=>invitationDate(props.event))
const state=computed(()=>eventState(props.event,props.now))
const replay=computed(()=>eventReplayLink(props.event,import.meta.env.VITE_YOUTUBE_HANDLE))
const game=computed(()=>{const names=eventGameNames(props.event);return names.nameEs||names.nameEn})
</script>
<template>
  <article class="event-news-card" :class="{'is-featured':event.featured&&emphasize}">
    <button type="button" class="event-cover" :aria-label="'Ver detalles de '+event.title" @click="emit('details')"><img :src="resolveAssetUrl(event.backgroundUrl||event.imageUrl,defaultBannerUrl)" alt="" loading="lazy"/><span class="event-type-badge">{{ event.type||'Evento' }}</span><span v-if="event.featured" class="featured-badge"><i class="fas fa-star" aria-hidden="true"></i> Destacado</span></button>
    <div class="event-copy">
      <div class="event-schedule"><time><i class="far fa-calendar" aria-hidden="true"></i> {{ date.date }} · {{ date.time }}</time><span class="event-status" :class="state">{{ eventStateLabel(event,now) }}</span></div>
      <h2><button type="button" @click="emit('details')">{{ event.title }}</button></h2>
      <p class="event-description">{{ event.description||'Una nueva cita con Galaxia Nintendera.' }}</p>
      <a v-if="state==='past'" class="event-replay" :href="replay.href" target="_blank" rel="noopener noreferrer"><i class="fab fa-youtube" aria-hidden="true"></i> {{ replay.label }} <i class="fas fa-arrow-up-right-from-square" aria-hidden="true"></i></a>
      <div v-if="game||event.platform||communities.length" class="event-meta"><span v-if="game"><i class="fas fa-gamepad" aria-hidden="true"></i> {{ game }}</span><span v-if="event.platform">{{ event.platform }}</span><span v-for="community in communities.slice(0,2)" :key="community.id">{{ community.name }}</span></div>
      <footer><button class="event-details" type="button" @click="emit('details')">Ver detalles <i class="fas fa-arrow-right" aria-hidden="true"></i></button><div><button v-if="state!=='past'" class="notify" :class="{active:notified}" type="button" :disabled="notifyPending" :aria-pressed="notified" :aria-label="notified?'Quitar recordatorio':'Activar recordatorio'" @click="emit('notify')"><i :class="notified?'fas fa-bell':'far fa-bell'" aria-hidden="true"></i></button><button type="button" aria-label="Compartir evento" @click="emit('share')"><i class="fas fa-share-nodes" aria-hidden="true"></i></button></div></footer>
    </div>
  </article>
</template>
<style scoped>
