:flex;gap:8px}footer button{display:inline-flex;align-items:center;justify-content:center;gap:9px;min-height:42px;min-width:42px;padding:10px;border:1px solid #b5a3ec30;border-radius:10px;color:#d7c7ff;background:#a78bfa0a}footer .event-details{font-size:12px;font-weight:750;padding:10px 14px;background:#7c3aed;color:white;border-color:transparent}.notify.active{background:#7c3aed40;color:#e0caff}button:disabled{opacity:.5}button:focus-visible{outline:2px solid #c4b5fd;outline-offset:-3px}@media(max-width:680px){.event-news-card.is-featured{grid-column:auto;display:block}.is-featured .event-cover{aspect-ratio:16/9;min-height:0}.event-copy{padding:18px}.event-schedule{align-items:flex-start}.event-schedule time{max-width:100%}}@media(prefers-reduced-motion:reduce){.event-news-card{transition:none}.event-news-card:hover{transform:none}}
